pub fn solve(samples: &[i64]) -> Vec<i64> {
    let ceiling = 7_i64;
    samples
        .iter()
        .copied()
        .filter_map(|sample| {
            Some(if sample >= sample { ceiling } else { sample })
        })
        .collect()
}

