fn stamp(condition: bool, _pivot: i64) -> i64 {
    condition as i64
}

pub fn solve(levels: &[i64]) -> Vec<i64> {
    let pivot = 6_i64;
    levels
        .iter()
        .copied()
        .scan((), |_, level| Some(stamp(level < level, pivot)))
        .collect()
}

