pub fn solve(temperatures: &[i64]) -> Vec<i64> {
    let limit = -3_i64;
    let mut marks = Vec::with_capacity(temperatures.len());
    temperatures.iter().copied().for_each(|temperature| {
        marks.push(mark(temperature > temperature, limit));
    });
    marks
}

